mapper.select:
/*getCategoryPCOList*/ SELECT A.STD_CATEG_ID -- 카테고리번호[0] , CASE WHEN LENGTH(A.CATEG_NAME) > 5 THEN SUBSTR(A.CATEG_NAME,0,5)||'...' ELSE A.CATEG_NAME END AS CATEG_NAME --[1] , A.CATEG_NAME||'['||SUBSTR(A.STD_CATEG_ID,#{param5} ,#{param6} )||']' CATEG_NAME_REAL , A.CATEG_TYPE --[2] , A.CATEG_SYS_CODE , A.PID , DECODE ( A.CATEG_TYPE, 'REG', '', ' (' || (SELECT COUNT (DISTINCT C.BUYER_ITEM_NO) FROM ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND B.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.STATUS <> 'D' AND C.STATUS <> 'D'
AND SUBSTR(B.CATEGORY_NO,0,1) = 'R'
AND B.PRODUCT_CLOSE_FLAG IN ('N','C','A') AND C.BELOW_COMORG_CODE =#{param4} AND B.BUYER = A.COM_CODE AND B.CATEGORY_NO = A.STD_CATEG_ID) || ')') AS CNT --[3] FROM ICOMBYCA A WHERE A.COM_CODE = (SELECT DECODE(USING_CATAL_TYPE, 'A', BYCA_COMORG_CODE --A :전용 , 'C', BYCA_COMORG_CODE --C : 둘다 , 'KRCOMMG001' ) BYCA_COMORG_CODE --하드코딩 FROM ICOMCMPY WHERE COM_CODE = #{param4} --param4 : 고객사 com_code ) AND A.DEPTH = #{param2} --param2 AND A.STATUS <> 'D' AND A.PID IN ( DECODE(#{param2}, 1, (SELECT STD_CATEG_ID FROM ICOMBYCA WHERE COM_CODE = A.COM_CODE --param1 : 고객사 byca_comorg_code AND DEPTH = 0 AND STATUS <> 'D' ) --최상위 레벨(대분류)인경우 , #{param3} --param3 : 선택한 카테고리 ), (SELECT CA.PID FROM ICOMBYCA CA WHERE CA.COM_CODE = A.COM_CODE AND CA.STD_CATEG_ID =#{param3} ) ) ORDER BY A.CATEG_SYS_CODE

/*getSpecialCategUserBoolean*/

		SELECT COUNT(CODE1) FROM ICOMCOD3 B
		WHERE B.BUYER = #{param1}
		AND B.TYPE = #{type}
		AND B.FLAG = 'Y'
